import{z as l,x as B,o as A,c as s,q as o,j as e,D as a,d as i,s as t,S as r}from"./chunks/framework.C8m1ZpeB.js";const M=JSON.parse('{"title":"Nikon 对 ASML","description":"","frontmatter":{"title":"Nikon 对 ASML","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/nikon-vs-asml.md","filePath":"litho/nikon-vs-asml.md","lastUpdated":1791413859000}'),p={name:"litho/nikon-vs-asml.md"};function d(h,E,S,V,m,C){const n=B("Mermaid");return A(),s("div",null,[E[2]||(E[2]=o('<h1 id="nikon-对-asml" tabindex="-1">Nikon 对 ASML <a class="header-anchor" href="#nikon-对-asml" aria-label="Permalink to &quot;Nikon 对 ASML&quot;">​</a></h1><div class="epigraph"><p>浸没时代的领先扫描机不是物理上只可能有一家；公开史上，双工件台、浸没与后来的 EUV 集成，把可买到的先进机台收敛到 ASML 这条链上。</p><footer>—— 对照浸没光刻竞争的公开 Chronology；EUV 商业供应见 ASML / 出口管制公开事实</footer></div><p><a href="/litho/euv-export-control">上一课</a>把量产 EUV 写成一条商业供应链，并用许可制度解释它进不了部分市场。缺口是：这条集中从哪来。本课钉 Nikon 对 ASML 的公开竞争史——浸没阶段仍有对手，EUV 阶段公开可交货的是 ASML。不编市场份额百分数，不写未公开订单。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>出口管制课的前提是「EUV 扫描仪商业上只有 ASML」。读者会问：193 浸没不是还有 Nikon 吗？有。Canon 也曾做扫描机，后来退出领先逻辑这条赛道。公开史是：ArF 干式与浸没阶段，ASML 与 Nikon 都卖过先进扫描机；ASML 的 TWINSCAN 双工件台（一台测量、一台曝光）成为高吞吐架构的公开标杆；浸没 NA 走到 1.35 一类量产点后，客户在逻辑领先节点上越来越集中到 ASML 平台。EUV 则从一开始就是 ASML + 蔡司投影 + Cymer 光源的垂直整合，Nikon 没有对等的量产 EUV 产品线进入同一市场。</p><p>本课要的是这条<strong>公开叙事</strong>，不是把管制原因写成「因为 Nikon 输了」。管制管的是已存在的 EUV 供应链；竞争史解释为何浸没高端也被同一家深度占据。</p><h3 id="不要把「谁赢了」写成物理定律" tabindex="-1">不要把「谁赢了」写成物理定律 <a class="header-anchor" href="#不要把「谁赢了」写成物理定律" aria-label="Permalink to &quot;不要把「谁赢了」写成物理定律&quot;">​</a></h3><p>双工件台提高可用性与套刻闭环效率，不是光学 NA 公式。浸没液、镜头、工件台、光源、软件一起才是机台。Nikon 继续提供浸没机给特定市场与节点，公开事实允许「仍有第二家浸没供应商」，同时允许「领先逻辑 EUV 产线以 ASML 为商业来源」。两句都要写，才不会变成宣传稿。</p><p><span class="marginnote">禁止编造全球份额、台数或营收比。课标只使用架构事实、产品代际的公开存在、以及 EUV 商业供应关系。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读史按层：干式 ArF 多家 → 浸没引入后 ASML/Nikon 公开竞赛 → 双工件台与浸没高 NA 的系统集成差异显现于客户选择 → EUV 研发投入与蔡司/Cymer 绑定使量产 EUV 只有一条交货链。中国节点课要写国产浸没与多重曝光，前提正是：没有 EUV 时，浸没机（含 Nikon 与其它）仍是物理工具；有 EUV 的那条成本曲线被管制钉住。</p><p><span class="marginnote">术语翻译：TWINSCAN 双工件台就是「一台机器里放两个台子，一个在曝光晶圆，另一个同时在测量对准下一片」。传统单台机器曝光时不能测量，测量时不能曝光；并行化把这段等待藏起来了。直觉类比：像餐厅两个灶台，一个炒菜、一个备料，出餐速度自然快——这不是锅（光学）变好了，是流程编排变了。</span></p><p>写供应链时分开：浸没镜头与 EUV 多层投影不是同一货架。蔡司 EUV POB 的公开绑定是 EUV 集中的技术原因之一，不要把浸没镜头竞争直接外推。</p>',13)),(A(),e(r,null,{default:a(()=>[t(n,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20CAL%5B%22%E5%9C%A8%E6%9F%90%E4%BB%A3%E6%89%AB%E6%8F%8F%E6%9C%BA%E4%B8%8A%E6%A0%87%E5%AE%9A%E5%B7%A5%E8%89%BA%E5%8C%85%22%5D%20--%3E%20PKG%5B%22OPC%20%E6%A8%A1%E5%9E%8B%20%2F%20%E5%A5%97%E5%88%BB%E6%A8%A1%E5%9E%8B%20%2F%20%E8%83%B6%E4%B8%8E%E7%85%A7%E6%98%8E%E9%85%8D%E6%96%B9%22%5D%0A%20%20PKG%20--%3E%20YLD%5B%22%E9%87%8F%E4%BA%A7%E8%89%AF%E7%8E%87%E4%B8%8E%20on-product%20overlay%22%5D%0A%20%20PKG%20--%3E%7C%22%E6%8D%A2%E4%BE%9B%E5%BA%94%E5%95%86%3F%22%7C%20REDO%5B%22%E9%87%8D%E5%81%9A%20DTCO%3A%20%E9%87%8D%E6%A0%87%E5%AE%9A%E5%85%A8%E9%83%A8%E9%85%8D%E6%96%B9%22%5D%0A%20%20REDO%20--%3E%20COST%5B%22%E6%95%B0%E6%9C%88%E5%81%9C%E7%BA%BF%E4%B8%8E%E9%A3%8E%E9%99%A9%22%5D%0A%20%20COST%20--%3E%20STAY%5B%22%E5%AE%A2%E6%88%B7%E5%80%BE%E5%90%91%E7%95%99%E5%9C%A8%E5%8E%9F%E5%B9%B3%E5%8F%B0%22%5D%0A%20%20STAY%20--%3E%20CAL%0A%20%20EUVB%5B%22EUV%3A%20%E5%85%89%E6%BA%90%2B%E7%9C%9F%E7%A9%BA%E5%8F%B0%2B%E5%A4%9A%E5%B1%82%E9%95%9C%E7%BB%91%E5%AE%9A%22%5D%20--%3E%20STAY%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[i(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=o('<h3 id="与出口管制的接口" tabindex="-1">与出口管制的接口 <a class="header-anchor" href="#与出口管制的接口" aria-label="Permalink to &quot;与出口管制的接口&quot;">​</a></h3><p>管制对象是 ASML 的 EUV（以及后来的高端浸没许可实践），不是「禁止 Nikon 存在」。先进逻辑若只被禁止买 EUV，仍可能买或用已安装的浸没做多重图形，见 <a href="/litho/china-duv-multipattern">国产 DUV 多重曝光</a>。竞争史解释工具菜单有多窄，不管制条款本身。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>客户锁定来自工艺包与机台生态：OPC、套刻模型、胶与照明配方在某一代扫描机上标定，换供应商等于重做 DTCO。双工件台把测量与曝光并行，吞吐与 on-product overlay 的工程闭环更紧，这是公开架构优势，不是一句「光学更好」。EUV 再把光源、真空台、多层镜加成更高的进入壁垒。于是浸没阶段的领先地位与 EUV 研发投入互相放大。</p><p>Nikon 的公开位置：浸没扫描机供应商之一，EUV 量产交货未进入与 ASML 对等的逻辑产线叙事。写「对」不是写「消灭」。</p><p><span class="marginnote">常见误区：初学者容易把「领先逻辑只用 ASML」读成物理定律——好像只有它家光学能成像。实际上这是生态锁定的结果：机台、OPC 软件、胶配方、镜头供应链互相咬合，换一家等于全套重来，没人愿意为一个物理上差不多好的方案付出数月停线。「谁赢了」是商业与工程集成的故事，不是 NA 公式算出来的。</span></p><p><span class="marginnote">Canon 退出领先扫描机赛道是公开史的一部分，但本课标题是 Nikon 对 ASML，不把第三家的内部决策写进未公开原因。</span></p>',7)),(A(),e(r,null,{default:a(()=>[t(n,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20TD%0A%20%20DRY%5B%22%E5%B9%B2%E5%BC%8F%20ArF%20%E5%A4%9A%E5%AE%B6%22%5D%20--%3E%20IMM%5B%22%E6%B5%B8%E6%B2%A1%3A%20ASML%20%E4%B8%8E%20Nikon%22%5D%0A%20%20IMM%20--%3E%20DUAL%5B%22%E5%8F%8C%E5%B7%A5%E4%BB%B6%E5%8F%B0%E7%AD%89%E7%B3%BB%E7%BB%9F%E9%9B%86%E6%88%90%22%5D%0A%20%20IMM%20--%3E%20EUV%5B%22%E9%87%8F%E4%BA%A7%20EUV%3A%20ASML%20%E9%93%BE%22%5D%0A%20%20EUV%20--%3E%20CTRL%5B%22%E5%87%BA%E5%8F%A3%E8%AE%B8%E5%8F%AF%E9%92%89%E4%BD%8F%20EUV%20%E6%89%A9%E6%95%A3%22%5D%0A%20%20IMM%20--%3E%20MULTI%5B%22%E6%97%A0%20EUV%20%E5%88%99%E6%B5%B8%E6%B2%A1%E5%A4%9A%E9%87%8D%E5%9B%BE%E5%BD%A2%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[i(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=o('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重写 ECCN 条款，也不评价未公开的客户谈判。禁止份额数字、禁止内部路线图。浸没镜头、光源和工件台仍可分开讨论；EUV 把三者绑进同一交货链，这才是「对 ASML」在本课的终点。后课国产浸没与多重曝光默认：工具菜单里仍有浸没机，没有对等的量产 EUV。</p><p>引用公开产品史、ASML TWINSCAN / EUV 公开叙述、Nikon 作为浸没供应商的公开存在。</p><p><span class="marginnote">「只有 ASML 能做 EUV」指商业量产扫描仪供应链，不是声称其它实验室光源物理上不可能发光。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>浸没阶段 ASML 与 Nikon 都是公开竞争对手；领先逻辑后来集中到 ASML 平台。</li><li>双工件台等系统集成是公开架构差异，不是 NA 公式注定。</li><li>量产 EUV 商业链是 ASML + 蔡司 + Cymer；Nikon 未进入对等交货叙事。</li><li>不管制史实、不编份额；管制课管的是这条已存在的链。</li><li>客户锁定来自工艺包与机台生态，换供应商等于重做 DTCO。</li><li>出处：浸没竞争公开史；ASML / 管制公开事实。</li></ul>',6))])}const k=l(p,[["render",d]]);export{M as __pageData,k as default};
